WITH latest AS (SELECT id, store_id, product_id, sale_date, units, revenue FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id, product_id ORDER BY revenue, id) AS dedup_rank FROM store_sales) t WHERE dedup_rank = 1), base AS (SELECT *, DATEDIFF(CURRENT_DATE(), sale_date) AS days_since_sale_date FROM latest WHERE revenue >= 2900), valid AS (SELECT id, store_id, product_id, sale_date, units, revenue, days_since_sale_date, COALESCE(days_since_sale_date, 0) AS days_since_sale_date_filled, days_since_sale_date - units AS days_since_sale_date_minus_units FROM base WHERE sale_date >= DATE '2023-06-04' AND product_id IN (2, 3, 9, 10)), latest_store_sales AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY revenue DESC NULLS LAST, id) AS dedup_rank FROM valid QUALIFY dedup_rank = 1) SELECT id, store_id, product_id, sale_date, units, revenue, days_since_sale_date_filled FROM latest_store_sales ORDER BY product_id DESC NULLS FIRST, sale_date;
